// Live 3D twin of the hexapod, driven by the same commanded servo angles as
// the sliders. Geometry comes from twin_model.json, generated by
// vorpal-mujoco/build_neutral.py from the same data as hexapod_neutral.xml, so
// this view and MuJoCo can't disagree. Joint convention matches MuJoCo
// (right-hand rotation about the joint axis), so a channel mapping confirmed
// here transfers straight to the sim.
//
// Channel -> joint mapping: sim angle = sign * (servo - 90) + offset, edited
// in the "Channel mapping" table and saved on the board (/mapping).
import * as THREE from 'three';
import { STLLoader } from 'three/addons/loaders/STLLoader.js';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

const NUM = 12;
const JOINTS = ['none', ...[0, 1, 2, 3, 4, 5].map((k) => `hip${k}`), ...[0, 1, 2, 3, 4, 5].map((k) => `knee${k}`)];
// Confirmed on the real robot 2026-10-04 (L0 = front leg). Hip servos turn
// opposite to the sim's +, so every hip has sign -1.
const CONFIRMED = { 0: [0, 6], 1: [3, 9], 2: [4, 10], 3: [5, 11], 4: [2, 8], 5: [1, 7] }; // leg -> [hip ch, knee ch]
const defaultMapping = () => {
  const m = new Array(NUM);
  for (const [k, [h, kn]] of Object.entries(CONFIRMED)) {
    m[h] = { joint: `hip${k}`, sign: -1, offset: 0 };
    m[kn] = { joint: `knee${k}`, sign: 1, offset: 0 };
  }
  return m;
};

let mapping = defaultMapping();
const servo = new Array(NUM).fill(90);
const joints = {};      // name -> { obj, axis }
const legMats = [];     // per sim leg: materials to highlight
const kneeJs = [];      // per sim leg: knee joint group (debug/verification)
let renderer, scene, camera, controls;

// Draw only when something changed. A nonstop render loop of this scene ran at
// ~6 fps in the desktop app's browser and starved the animation timers.
let renderPending = false;
function requestRender() {
  if (renderPending || !renderer) return;
  renderPending = true;
  requestAnimationFrame(() => { renderPending = false; renderer.render(scene, camera); });
}

const deg = (d) => (d * Math.PI) / 180;

function mat4(rowMajor) {
  const m = new THREE.Matrix4();
  m.set(...rowMajor);
  return m;
}

function fixedGroup(matrix) {
  const g = new THREE.Group();
  g.matrixAutoUpdate = false;
  g.matrix.copy(matrix);
  return g;
}

function textSprite(text) {
  const c = document.createElement('canvas');
  c.width = 128; c.height = 64;
  const ctx = c.getContext('2d');
  ctx.font = 'bold 44px sans-serif';
  ctx.fillStyle = '#fff';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, 64, 32);
  const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: new THREE.CanvasTexture(c), depthTest: false }));
  s.scale.set(0.03, 0.015, 1);
  return s;
}

function applyJoints() {
  for (const j of Object.values(joints)) j.obj.quaternion.identity();
  mapping.forEach((m, ch) => {
    const j = joints[m.joint];
    if (!j) return;
    j.obj.quaternion.setFromAxisAngle(j.axis, deg(m.sign * (servo[ch] - 90) + m.offset));
  });
  requestRender();
}

function legOfChannel(ch) {
  const m = mapping[ch].joint.match(/(\d)$/);
  return m ? Number(m[1]) : null;
}

const flashTimers = {};
function flashLeg(k) {
  if (k === null) return;
  legMats[k].forEach((mt) => mt.emissive.setHex(0x664400));
  requestRender();
  clearTimeout(flashTimers[k]);
  flashTimers[k] = setTimeout(() => { legMats[k].forEach((mt) => mt.emissive.setHex(0x000000)); requestRender(); }, 700);
}

let saveTimer = null;
function saveMapping() {
  clearTimeout(saveTimer);
  saveTimer = setTimeout(() => {
    fetch(`/mapping?m=${encodeURIComponent(JSON.stringify(mapping))}`, { method: 'POST' });
  }, 300);
}

function buildMappingTable() {
  const tbody = document.querySelector('#map-table tbody');
  tbody.innerHTML = '';
  mapping.forEach((m, ch) => {
    const tr = document.createElement('tr');
    tr.innerHTML =
      `<td>ch ${ch}</td>` +
      `<td><select>${JOINTS.map((j) => `<option ${j === m.joint ? 'selected' : ''}>${j}</option>`).join('')}</select></td>` +
      `<td><button class="sign">${m.sign > 0 ? '+' : '−'}</button></td>` +
      `<td><input type="number" step="1" value="${m.offset}"></td>`;
    const [sel, btn, off] = [tr.querySelector('select'), tr.querySelector('button'), tr.querySelector('input')];
    sel.addEventListener('change', () => { m.joint = sel.value; applyJoints(); flashLeg(legOfChannel(ch)); saveMapping(); });
    btn.addEventListener('click', () => { m.sign = -m.sign; btn.textContent = m.sign > 0 ? '+' : '−'; applyJoints(); saveMapping(); });
    off.addEventListener('input', () => { m.offset = Number(off.value) || 0; applyJoints(); saveMapping(); });
    tbody.appendChild(tr);
  });
  const bulk = (fn) => () => { mapping.forEach(fn); buildMappingTable(); applyJoints(); saveMapping(); };
  document.getElementById('map-reset').onclick = () => { mapping = defaultMapping(); buildMappingTable(); applyJoints(); saveMapping(); };
  // channels numbered the other way around the body: leg k <-> leg (6-k)%6, ch 0 stays L0
  document.getElementById('map-reverse').onclick = bulk((m) => {
    m.joint = m.joint.replace(/(\d)$/, (d) => String((6 - Number(d)) % 6));
  });
  document.getElementById('map-flip-hips').onclick = bulk((m) => { if (m.joint.startsWith('hip')) m.sign = -m.sign; });
  document.getElementById('map-flip-knees').onclick = bulk((m) => { if (m.joint.startsWith('knee')) m.sign = -m.sign; });
}

async function init() {
  const model = await (await fetch('twin_model.json')).json();
  try {
    const saved = (await (await fetch('/mapping')).json()).mapping;
    if (Array.isArray(saved) && saved.length === NUM) mapping = saved;
  } catch (e) { /* no saved mapping yet */ }

  const host = document.getElementById('sim3d');
  renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.5));
  renderer.setSize(host.clientWidth, host.clientHeight);
  host.appendChild(renderer.domElement);

  scene = new THREE.Scene();
  scene.background = new THREE.Color(0x15171c);
  camera = new THREE.PerspectiveCamera(40, host.clientWidth / host.clientHeight, 0.005, 5);
  camera.up.set(0, 0, 1);
  camera.position.set(0.28, -0.32, 0.22);
  controls = new OrbitControls(camera, renderer.domElement);
  controls.target.set(0, 0, -0.035);
  controls.update();
  controls.addEventListener('change', requestRender);

  scene.add(new THREE.HemisphereLight(0xffffff, 0x333344, 1.2));
  const sun = new THREE.DirectionalLight(0xffffff, 1.6);
  sun.position.set(0.3, -0.2, 0.6);
  scene.add(sun);
  const grid = new THREE.GridHelper(0.5, 25, 0x444a55, 0x2a2e36);
  grid.rotation.x = Math.PI / 2;
  grid.position.z = -0.09;
  scene.add(grid);

  const loader = new STLLoader();
  const [gBase, gHinge, gLeg] = await Promise.all(
    ['base', 'hinge', 'leg'].map((k) => loader.loadAsync(model.meshes[k])));
  [gBase, gHinge, gLeg].forEach((g) => g.computeVertexNormals());
  const s = model.mesh_scale;
  const mesh = (geom, mat) => { const m = new THREE.Mesh(geom, mat); m.scale.setScalar(s); return m; };

  scene.add(mesh(gBase, new THREE.MeshStandardMaterial({ color: 0x4a55c8, roughness: 0.7 })));

  model.hips.forEach((h, k) => {
    const hingeMat = new THREE.MeshStandardMaterial({ color: 0xf2c11a, roughness: 0.6 });
    const legMat = new THREE.MeshStandardMaterial({ color: 0x3f74e0, roughness: 0.6 });
    legMats[k] = [hingeMat, legMat];

    const hipFixed = new THREE.Group();
    hipFixed.position.set(...h.pos);
    hipFixed.rotation.z = deg(h.yaw_deg);
    scene.add(hipFixed);
    const hipJ = new THREE.Group();
    hipFixed.add(hipJ);
    joints[`hip${k}`] = { obj: hipJ, axis: new THREE.Vector3(0, 0, 1) };

    model.hinges_in_hip.forEach((T) => {
      const g = fixedGroup(mat4(T));
      g.add(mesh(gHinge, hingeMat));
      hipJ.add(g);
    });

    const kneeFixed = new THREE.Group();
    kneeFixed.position.set(...model.knee_in_hip);
    hipJ.add(kneeFixed);
    const kneeJ = new THREE.Group();
    kneeFixed.add(kneeJ);
    kneeJs[k] = kneeJ;
    joints[`knee${k}`] = { obj: kneeJ, axis: new THREE.Vector3(...model.knee_axis).normalize() };
    const legG = fixedGroup(mat4(model.leg_in_knee));
    legG.add(mesh(gLeg, legMat));
    kneeJ.add(legG);

    const label = textSprite(`L${k}`);
    const a = deg(h.yaw_deg);
    label.position.set(0.155 * Math.cos(a), 0.155 * Math.sin(a), 0.01);
    scene.add(label);
  });

  buildMappingTable();
  applyJoints();

  window.addEventListener('resize', () => {
    camera.aspect = host.clientWidth / host.clientHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(host.clientWidth, host.clientHeight);
    requestRender();
  });
  requestRender();
}

// Same interface the page already uses (was the old 2D twin.js).
window.Twin = {
  init,
  // sim joint angles (deg, 0 = neutral) -> 12 servo angles via the mapping:
  // sim = sign*(servo-90)+offset  =>  servo = 90 + (sim-offset)/sign
  simPoseToServos(jointNames, simDegs) {
    const byJoint = Object.fromEntries(jointNames.map((j, i) => [j, simDegs[i]]));
    return mapping.map((m, ch) => {
      if (!(m.joint in byJoint)) return servo[ch];
      return Math.max(0, Math.min(180, 90 + (byJoint[m.joint] - m.offset) / m.sign));
    });
  },
  // world 4x4 (column-major, three.js) of leg k's knee frame - used to verify
  // this view against MuJoCo's hexapod_neutral.xml
  _kneeFrame(k) { kneeJs[k].updateWorldMatrix(true, false); return kneeJs[k].matrixWorld.elements.slice(); },
  setChannel(ch, angle) {
    servo[ch] = angle;
    if (Object.keys(joints).length) { applyJoints(); flashLeg(legOfChannel(ch)); }
  },
};
